// aes-cbc.mjs — AES-128 CBC mode of operation, mirroring pyaes'
// AESModeOfOperationCBC interface. Chaining state is kept across
// encrypt() calls: each plaintext block is XORed with the previous
// ciphertext block (or the IV for the first block) before encryption.

import { expandKey, encryptBlock } from './aes-core.mjs';

export class AESModeOfOperationCBC {
  // key: Uint8Array(16), iv: Uint8Array(16)
  constructor(key, iv) {
    this._roundKeys = expandKey(key);
    this._iv = iv.slice();
  }

  // block: Uint8Array(16) -> Uint8Array(16) ciphertext
  encrypt(block) {
    const xored = new Uint8Array(16);
    for (let i = 0; i < 16; i++) xored[i] = block[i] ^ this._iv[i];
    const cipher = encryptBlock(xored, this._roundKeys);
    this._iv = cipher.slice();
    return cipher;
  }
}

// test17.mjs — Node.js ESM port of the pyaes AES-128 CBC script.
// Prints each 16-byte ciphertext block via Python's repr(bytes).

import { parseArgs } from './args.mjs';
import { AESModeOfOperationCBC } from './aes-cbc.mjs';
import { bytesRepr } from './pyrepr.mjs';

const args = parseArgs(process.argv.slice(2));

const aes = new AESModeOfOperationCBC(
  Buffer.from(args.key, 'utf8'),
  Buffer.from(args.iv, 'utf8')
);
const data = Buffer.from(args.data, 'utf8');

const ciphertexts = [];
for (let i = 0; i < data.length; i += 16) {
  const cipher = aes.encrypt(data.subarray(i, i + 16));
  ciphertexts.push(cipher);
}
for (const cipher of ciphertexts) {
  console.log(bytesRepr(cipher));
}
